b=Path(__file__).parent;p='06-circuit-rune-p1';src=b/f'cockpit-compositions/{p}-composed-raw.png';key=b/f'processed-phase-atlases/{p}-composed-prototype-source-keyed-rgba.png';mask=b/f'cockpit-compositions/{p}-native-cockpit-mask.png';original=np.array(Image.open(src).convert('RGBA'));a=np.array(Image.open(key).convert('RGBA'));rgb=original[:,:,:3].astype(float);native=np.array(Image.open(mask).convert('L'))>0;out=a.copy();mn=np.minimum(rgb[:,:,0],rgb[:,:,2]);balanced=abs(rgb[:,:,0]-rgb[:,:,2])<=18
